import {CHANNELS,CHANNEL_METRICS,primaryChannel,metricValue,barPair} from './channel-metrics.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>{try{const u=new URL(url);return /^https?:$/.test(u.protocol)?`<a href="${esc(u.href)}" target="_blank" rel="noopener">${esc(label)}</a>`:''}catch{return ''}};
const gaps={access_restricted:'Access restricted',unavailable:'Page unavailable',login_or_script_required:'Login / app needed',counts_not_public:'Counts not shown',not_sampled:'Not sampled'};
export function channelCharts(r,reference){return `<section class="channel-charts"><h3>Channel footprint</h3><p class="small-note">Public account counts · ${esc(r.socialInfo?.lastScan?.slice(0,10)||'Not sampled')}<br>Each pair compares the same measure. Orange: this account. Grey: Rainbow Town account.</p><div class="channel-grid">${CHANNELS.map(platform=>{const c=primaryChannel(r,platform),base=primaryChannel(reference||{},platform),observed=CHANNEL_METRICS.filter(([k])=>metricValue(c,k));return `<article class="channel-card"><header><strong>${esc(platform)}</strong>${c?link(c.url,'Account ↗'):''}</header>${observed.length?observed.map(([key,label])=>{const m=metricValue(c,key),b=metricValue(base,key),bars=barPair(m.value,b?.value??null);return `<div class="channel-measure"><div class="measure-label"><span>${esc(label)}</span><strong>${m.approximate?'≈ ':''}${m.value.toLocaleString()}</strong></div><div class="channel-bar" aria-label="${esc(label)}: ${m.value}"><span style="width:${bars.value}%"></span></div>${b?`<div class="channel-bar reference-bar" aria-label="Rainbow Town ${esc(label)}: ${b.value}"><span style="width:${bars.reference}%"></span></div><span class="comparison-note">Rainbow: ${b.approximate?'≈ ':''}${b.value.toLocaleString()}</span>`:'<span class="comparison-note">Reference not available</span>'}</div>`}).join(''):`<div class="channel-gap">${esc(c?(gaps[c.status]||'Counts not shown'):'Account not identified')}</div>`}${c?`<span class="small-note">${esc(c.scopeLabel)}<br>Checked ${esc(c.checked?.slice(0,10))}</span>`:''}${c?.metrics.some(m=>m.metric==='talking_about')?'<span class="small-note">Discussion window is not stated by the page.</span>':''}${(r.socialInfo?.channels||[]).filter(x=>x.platform===platform&&x!==c).length?`<details class="other-accounts"><summary>Other linked accounts</summary>${r.socialInfo.channels.filter(x=>x.platform===platform&&x!==c).map(x=>`${link(x.url,x.title||platform)}<span class="small-note">${x.metrics.map(m=>`${esc(m.label)}: ${esc(m.display)}`).join(' · ')||'Counts unavailable'}</span>`).join('')}</details>`:''}</article>`}).join('')}<article class="channel-card" data-channel-maps="${esc(r.id)}"><header><strong>Google Maps</strong></header><div class="channel-gap">${r.placeId&&r.mapPrecision!=='mall'?'Loading public reviews…':'Venue listing not verified'}</div></article></div><details class="channel-notes"><summary>What these numbers mean</summary><p>Followers, page likes, lifetime posts and check-ins are different measures. Bars use a separate scale for each measure and are not added into a total. Missing counts are unknown, not zero. Approximate numbers retain the source’s rounding.</p><p>Brand accounts can cover multiple sites or countries. Rainbow Town’s account is shared; these totals do not isolate Glen Waverley or Braeside. The requested heat reference stays 100, but a comparable 30-day activity sample is still needed before calculating other heat scores.</p></details></section>`;}
export function setupChannelCharts({findRecord,reference,getPlace,detail}){
 let popover=null,anchor=null,timer;
 function hide(){clearTimeout(timer);anchor?.setAttribute('aria-expanded','false');popover?.remove();popover=null;anchor=null;}
 async function loadMaps(root,r){const el=root.querySelector('[data-channel-maps]');if(!el||!r.placeId||r.mapPrecision==='mall')return;try{const p=await getPlace(r);if(!el.isConnected)return;const count=Number.isFinite(p?.userRatingCount)?p.userRatingCount:null;const base=reference();let bp=null;try{if(base?.placeId)bp=await getPlace(base)}catch{}if(!el.isConnected)return;const bc=Number.isFinite(bp?.userRatingCount)?bp.userRatingCount:null,pair=barPair(count,bc);el.innerHTML=`<header><strong>Google Maps</strong>${link(p?.googleMapsUri,'Listing ↗')}</header>${count!==null?`<div class="measure-label"><span>Total reviews</span><strong>${count.toLocaleString()}</strong></div><div class="channel-bar"><span style="width:${pair.value}%"></span></div>${bc!==null?`<div class="channel-bar reference-bar"><span style="width:${pair.reference}%"></span></div><span class="comparison-note">Rainbow Glen Waverley: ${bc.toLocaleString()}</span>`:""}<span class="small-note">${p.rating?'Rating: '+p.rating+' / 5 · ':''}Live listing total</span>`:'<div class="channel-gap">Review count not published</div>'}<span class="maps-attribution" translate="no">Google Maps</span><span class="small-note">All-time reviews · no revenue estimate</span>`;}catch{if(el.isConnected){el.innerHTML='<header><strong>Google Maps</strong></header><div class="channel-gap">Reviews unavailable</div><button class="link-button">Retry</button>';el.querySelector('button').onclick=()=>loadMaps(root,r)}}}
 function scheduleHide(){clearTimeout(timer);timer=setTimeout(()=>{if(popover?.matches(':hover')||popover?.contains(document.activeElement)||anchor===document.activeElement)return;hide()},250);}
 function show(button){clearTimeout(timer);if(anchor===button&&popover)return;hide();const r=findRecord(button.dataset.social);if(!r)return;anchor=button;anchor.setAttribute('aria-expanded','true');const box=document.createElement('div');box.className='channel-popover';box.setAttribute('role','region');box.setAttribute('aria-label',r.name+' channel data');box.innerHTML=`<div class="channel-popover-top"><strong>${esc(r.name)}</strong><button class="icon-button" aria-label="Close channel chart">×</button></div>${channelCharts(r,reference())}`;(button.closest('dialog')||document.body).append(box);popover=box;const rect=button.getBoundingClientRect(),width=Math.min(480,innerWidth-24);box.style.width=width+'px';const side=rect.left>=width+20?'left':innerWidth-rect.right>=width+20?'right':null;box.style.left=(side==='left'?rect.left-width-10:side==='right'?rect.right+10:Math.max(12,Math.min(rect.left,innerWidth-width-12)))+'px';if(side){box.style.top=Math.max(12,Math.min(rect.top,innerHeight-box.getBoundingClientRect().height-12))+'px'}else{const below=innerHeight-rect.bottom-20,above=rect.top-20;if(below>=220||below>=above){box.style.maxHeight=Math.max(100,below)+'px';box.style.top=(rect.bottom+8)+'px'}else{box.style.maxHeight=Math.max(100,above)+'px';box.style.top=Math.max(12,rect.top-box.getBoundingClientRect().height-8)+'px'}}box.querySelector('button').onclick=hide;box.addEventListener('pointerenter',()=>clearTimeout(timer));box.addEventListener('pointerleave',scheduleHide);box.addEventListener('focusin',()=>clearTimeout(timer));box.addEventListener('focusout',scheduleHide);loadMaps(box,r);}
 document.addEventListener('pointerover',e=>{const b=e.target.closest('[data-social]');if(b&&e.pointerType!=='touch')show(b)});
 document.addEventListener('pointerout',e=>{if(e.target.closest('[data-social]'))scheduleHide()});
 document.addEventListener('focusin',e=>{const b=e.target.closest('[data-social]');if(b)show(b)});
 document.addEventListener('focusout',e=>{if(e.target.closest('[data-social]'))scheduleHide()});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-social]');if(b){show(b);return}if(popover&&!popover.contains(e.target))hide()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&popover){e.preventDefault();e.stopImmediatePropagation();hide()}},true);
 window.addEventListener('resize',hide);detail.addEventListener('close',hide);
 return {hide,loadMaps};
}
